mapper.select:
/* SQL ID : MsgSndrDsctnDAO.selectSndrDsctnList 설 명 : 발송내역 목록 조회 */ SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY CH.SNDNG_DTTM DESC) AS LINE_NO , COUNT(*) OVER () AS TOTAL_CNT , CH.SNDNG_GBNCD , CH.SNDNGR_ID , MSG.MSG_ID , SBJCT.SBJCT_YR , SC.SMSTR_CHRTNM AS SBJCT_SMSTR , ORG.ORGNM , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , TRGTR.RCVRNM , (SELECT MAX(UC.CNTCT) FROM TB_LMS_USER_CNTCT UC WHERE UC.USER_ID = CH.RCVR_ID AND UC.CNTCT_TYCD = 'MBL_PHN') AS RCVR_TELNO , CH.SNDNG_DTTM , CH.SNDNG_YN , CH.SNDNG_STSCD FROM (
) CH INNER JOIN TB_LMS_MSG MSG ON CH.MSG_ID = MSG.MSG_ID LEFT JOIN TB_LMS_SBJCT SBJCT ON MSG.SBJCT_ID = SBJCT.SBJCT_ID LEFT JOIN TB_LMS_SMSTR_CHRT SC ON SBJCT.SMSTR_CHRT_ID = SC.SMSTR_CHRT_ID LEFT JOIN TB_LMS_ORG ORG ON SC.ORG_ID = ORG.ORG_ID LEFT JOIN TB_LMS_MSG_RCV_TRGTR TRGTR ON CH.MSG_ID = TRGTR.MSG_ID AND CH.RCVR_ID = TRGTR.USER_ID WHERE 1 = 1
) WHERE LINE_NO BETWEEN #{firstIndex} AND #{lastIndex} ORDER BY LINE_NO

/* SQL ID : MsgSndrDsctnDAO.selectSndrDsctnExcelList 설 명 : 발송내역 엑셀 목록 조회 */ SELECT ROW_NUMBER() OVER (ORDER BY CH.SNDNG_DTTM DESC) AS RNUM , CH.SNDNG_GBNCD , SBJCT.SBJCT_YR , SC.SMSTR_CHRTNM AS SBJCT_SMSTR , ORG.ORGNM , SBJCT.SBJCTNM , SBJCT.DVCLAS_NO , TRGTR.RCVRNM , (SELECT MAX(UC.CNTCT) FROM TB_LMS_USER_CNTCT UC WHERE UC.USER_ID = CH.RCVR_ID AND UC.CNTCT_TYCD = 'MBL_PHN') AS RCVR_TELNO , CH.SNDNG_DTTM , CH.SNDNG_YN , CH.SNDNG_RSLT_CD , CH.SNDNG_STSCD FROM (
) CH INNER JOIN TB_LMS_MSG MSG ON CH.MSG_ID = MSG.MSG_ID LEFT JOIN TB_LMS_SBJCT SBJCT ON MSG.SBJCT_ID = SBJCT.SBJCT_ID LEFT JOIN TB_LMS_SMSTR_CHRT SC ON SBJCT.SMSTR_CHRT_ID = SC.SMSTR_CHRT_ID LEFT JOIN TB_LMS_ORG ORG ON SC.ORG_ID = ORG.ORG_ID LEFT JOIN TB_LMS_MSG_RCV_TRGTR TRGTR ON CH.MSG_ID = TRGTR.MSG_ID AND CH.RCVR_ID = TRGTR.USER_ID WHERE 1 = 1
ORDER BY CH.SNDNG_DTTM DESC
